const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').split('\n');
const n = parseInt(input[0], 10);

// Conta quantos usuários têm cada senha distinta
const count = new Map();
for (let i = 1; i <= n; i++) {
  const s = input[i].trim();
  if (!s) continue;
  count.set(s, (count.get(s) || 0) + 1);
}

// Para cada cadeia u, M[u] = soma das contagens das senhas distintas s que contêm u como subcadeia
const M = new Map();
for (const [s, c] of count) {
  const L = s.length;
  for (let i = 0; i < L; i++) {
    for (let j = i + 1; j <= L; j++) {
      const sub = s.slice(i, j);
      M.set(sub, (M.get(sub) || 0) + c);
    }
  }
}

// Total = soma sobre cada senha t de c_t * M[t] (conta todos os pares, incluindo A=B) - N
let ans = 0;
for (const [t, c] of count) {
  ans += c * (M.get(t) || 0);
}

console.log(ans - n);
